package com.auramirage.app
import android.content.ContentValues
import android.content.Context
class NotesRepository(c:Context){private val h=NotesDbHelper(c.applicationContext);fun listNotes():List<Note>=h.readableDatabase.query("notes",null,"deleted_at IS NULL",null,null,null,"updated_at DESC").use{c->buildList{while(c.moveToNext())add(Note(c.getLong(c.getColumnIndexOrThrow("id")),c.getString(c.getColumnIndexOrThrow("title")),c.getString(c.getColumnIndexOrThrow("content")),c.getLongOrNull("folder_id"),c.getLong(c.getColumnIndexOrThrow("updated_at")),null))}};fun save(noteId:Long?,title:String,content:String,folderId:Long?=null):Long{val d=h.writableDatabase;val now=System.currentTimeMillis();val v=ContentValues().apply{put("title",NoteTitlePolicy.normalize(title,content));put("content",content);if(folderId==null)putNull("folder_id")else put("folder_id",folderId);put("updated_at",now);putNull("deleted_at")};val id=if(noteId==null)d.insertOrThrow("notes",null,v)else{d.update("notes",v,"id=?",arrayOf(noteId.toString()));noteId};d.insertOrThrow("revisions",null,ContentValues().apply{put("note_id",id);put("title",NoteTitlePolicy.normalize(title,content));put("content",content);put("created_at",now)});return id};fun delete(id:Long){h.writableDatabase.execSQL("UPDATE notes SET deleted_at=? WHERE id=?",arrayOf(System.currentTimeMillis(),id))};fun close()=h.close();private fun android.database.Cursor.getLongOrNull(n:String):Long?{val i=getColumnIndexOrThrow(n);return if(isNull(i))null else getLong(i)}}
